# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
            return out
    return out

# region: emit
def emit(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return render(shape(intake(emit(fold(raw)))))

